import json,re
from pathlib import Path

root=Path.cwd()
def loc(name,x,y,z=0,note='Direct fast travel'):
    return dict(name=name,x=x,y=y,z=z,note=note)
def npc(file,name):
    s=(root/f'src/main/java/com/perso/T4C/npc/{file}.java').read_text()
    a=re.search(r'@Spawn\((.*?)\)',s,re.S).group(1)
    x,y,z=[int(re.search(r'\b'+k+r'\s*=\s*(\d+)',a).group(1)) for k in ['x','y','z']]
    return loc(name,x,y,z,'Quest NPC · arrival beside the NPC')
grounds=json.loads((root/'assets/maps/worldmap/hunting-grounds.json').read_text())['grounds']
groups={
    'Cities':[loc('Lighthaven',2941,1062),loc('Windhowl',1723,1237),loc('Silversky',1495,2470,note="Requires Raven’s Dust access"),loc('Stonecrest',144,737)],
    'Hunting Areas':[loc(g['monster']+' Field',g['x'],g['y'],note='Direct access · dense hunting field') for g in grounds if not g.get('trainingTier')]+[loc('Arch Drake · Drake’s Lair',2850,2780,note='Direct access · Arch Drake boss')],
    'Training Fields':[loc('Tier '+str(g['trainingTier'])+' · '+g['family'],g['x'],g['y'],note='Direct access · matching monsters and champion') for g in grounds if g.get('trainingTier')],
    'Good Seraph Quest':[npc('BeltiganWhitesword','Sir Beltigan'),npc('Julian','Julian'),loc('Oracle access',2660,2610,2,'Requires Key of Artherk or Key of Ogrimar')],
    'Evil Seraph Quest':[npc('Mordenthal','Mordenthal'),npc('Vargus','Vargus'),loc('Oracle access',2660,2610,2,'Requires Key of Artherk or Key of Ogrimar')],
    'Olin Haad Quest':[npc('MonsignorDamien','Monsignor Damien'),npc('OlinHaad1','Olin Haad · Lighthaven')],
    'Gods':[],
    'New Islands':[loc('Witness Isles Sanctuary',4040,1477,note='Quest destination · unlock requirement shown here'),loc('Threnody Reach',5505,1150,note='Quest destination · unlock requirement shown here'),loc('The Hollow Dawn',5650,2290,note='Quest destination · unlock requirement shown here')],
    'Other Landmarks':[loc('Home',2951,1038),loc('Colosseum',1725,1825),loc('Tarantula Pond',773,1831),loc('Skraug Camp',601,172)]
}
quest_data=json.loads((root/'docs/spell-animations/quest-teleport-catalogue.json').read_text(encoding='utf-8'))
groups.update(quest_data['routes'])
s=(root/'src/main/java/com/perso/T4C/divine/DivinePantheon.java').read_text()
for name,school,x,y in re.findall(r'new God\("[^"]+", "([^"]+)", "([^"]+)", \d+, \d+, (\d+), (\d+),',s):
    groups['Gods'].append(loc(name,int(x),int(y),note=school.title()+' shrine · direct access'))
out=root/'docs/spell-animations'
if (out/'travel-runtime.json').exists():
    groups=json.loads((out/'travel-runtime.json').read_text(encoding='utf-8'))
