page=page.replace("groups[category].map((d,i)=>{const b=document.createElement('button');", "groups[category].map((d,i)=>{if(![d.name,d.chapter,d.note].join(' ').toLowerCase().includes(document.querySelector('#search').value.toLowerCase()))return null;const b=document.createElement('button');")
