page=page.replace("document.querySelector('#coords').textContent=d.x+', '+d.y+' · World '+d.z;", "document.querySelector('#coords').textContent=d.x===null?'Location pending':d.x+', '+d.y+' · World '+d.z;")
page=page.replace("document.querySelector('#detail').textContent=d.note;", "document.querySelector('#detail').replaceChildren(document.createTextNode(d.note));if(d.warning){const warning=document.createElement('p');warning.className='warning';warning.textContent=d.warning;document.querySelector('#detail').append(warning)}document.querySelector('#travel').disabled=!!d.warning;")
